func TestMiMCFiatShamir(t *testing.T) {
	fs := fiatshamir.NewTranscript(mimc.NewMiMC(), "c0")
	zero := make([]byte, mimc.BlockSize)
	err := fs.Bind("c0", zero)
	assert.NoError(t, err)
	_, err = fs.ComputeChallenge("c0")
	assert.NoError(t, err)
}

func TestByteOrder(t *testing.T) {
	assert := require.New(t)

	var buf [fr.Bytes]byte
	// if the 31 first bytes are FF, it's a valid FF in little endian, but not in big endian
	for i := range fr.Bytes - 1 {
		buf[i] = 0xFF
	}
	_, err := fr.BigEndian.Element(&buf)
	assert.Error(err)
	_, err = fr.LittleEndian.Element(&buf)
	assert.NoError(err)

	{
		// hashing buf with big endian should fail
		mimcHash := mimc.NewMiMC(mimc.WithByteOrder(fr.BigEndian))
		_, err := mimcHash.Write(buf[:])
		assert.Error(err)
	}

	{
		// hashing buf with little endian should succeed
		mimcHash := mimc.NewMiMC(mimc.WithByteOrder(fr.LittleEndian))
		_, err := mimcHash.Write(buf[:])
		assert.NoError(err)
	}

	buf = [fr.Bytes]byte{}
	// if the 31 bytes are FF, it's a valid FF in big endian, but not in little endian
	for i := 1; i < fr.Bytes; i++ {
		buf[i] = 0xFF
	}
	_, err = fr.BigEndian.Element(&buf)
	assert.NoError(err)
	_, err = fr.LittleEndian.Element(&buf)
	assert.Error(err)

	{
		// hashing buf with big endian should succeed
		mimcHash := mimc.NewMiMC(mimc.WithByteOrder(fr.BigEndian))
		_, err := mimcHash.Write(buf[:])
		assert.NoError(err)
	}

	{
		// hashing buf with little endian should fail
		mimcHash := mimc.NewMiMC(mimc.WithByteOrder(fr.LittleEndian))
		_, err := mimcHash.Write(buf[:])
		assert.Error(err)
	}
}

// knownDigest is the digest of the elements 1, 2, 3 written as bytes.
const knownDigest = "00dc43b5321160866937f9f11bfff239bec01757df11e4dbcfd020434e2482bb"

// TestMerkleDamgard checks the digest of a fixed input, also through the
// package-level Sum, and checks the hasher against the generic Merkle-Damgard
// hasher over [mimc.Compressor], see [hashtesting.CheckMatchesByteHasher].
func TestMerkleDamgard(t *testing.T) {
	var msg []byte
	for i := range uint64(3) {
		var e fr.Element
		e.SetUint64(i + 1)
		msg = append(msg, e.Marshal()...)
	}
	h := mimc.NewMiMC()
	_, err := h.Write(msg)
	require.NoError(t, err)
	require.Equal(t, knownDigest, hex.EncodeToString(h.Sum(nil)), "digest of 1, 2, 3")

	dgst, err := mimc.Sum(msg)
	require.NoError(t, err)
	require.Equal(t, knownDigest, hex.EncodeToString(dgst), "package-level Sum")

	newRef := func() hash.StateStorer {
		return hash.NewLargeFieldMerkleDamgardHasher[fr.Element, *fr.Element](mimc.Compressor{}, fr.Element{})
	}
	newHasher := func() hashtesting.Hasher[fr.Element, fr.Element] { return mimc.NewFieldHasher() }

	elems := make([]fr.Element, 7)
	fr.Vector(elems).MustSetRandom()
	short := make([]byte, 10)
	_, err = rand.Read(short)
	require.NoError(t, err)
	calls := []hashtesting.Call[fr.Element]{
		{Bytes: hashtesting.Marshal(elems[:3])},
		{Elements: elems[3:5]},
		{Bytes: short[:5]},
		{Bytes: append(elems[5].Marshal(), short[5:]...)},
		{}, // no elements
		{Elements: elems[6:]},
	}
	hashtesting.CheckMatchesByteHasher(t, newHasher, newRef, func(d fr.Element) []byte { return d.Marshal() }, calls)
}

func TestFieldHasher(t *testing.T) {
	assert := require.New(t)

	h1 := mimc.NewFieldHasher()
	h2 := mimc.NewFieldHasher()
	h3 := mimc.NewFieldHasher()
	randInputs := make(fr.Vector, 10)
	randInputs.MustSetRandom()

	for i := range randInputs {
		h1.Write(randInputs[i].Marshal())
		h2.WriteElement(randInputs[i])
	}
	dgst1 := h1.Sum(nil)
	dgst2 := h2.Sum(nil)
	assert.Equal(dgst1, dgst2, "hashes do not match")

	// test SumElement
	h3.WriteElement(randInputs[0])
	for i := 1; i < len(randInputs); i++ {
		h3.Write(randInputs[i].Marshal())
	}
	_dgst3 := h3.SumElement()
	dgst3 := _dgst3.Bytes()
	assert.Equal(dgst1, dgst3[:], "hashes do not match")

	// test SumElements
	h3.Reset()
	_dgst3 = h3.SumElements(randInputs)
	dgst3 = _dgst3.Bytes()
	assert.Equal(dgst1, dgst3[:], "hashes do not match")

	// test WriteField, SumField and PadBlock
	h4 := mimc.NewFieldHasher()
	h4.WriteField(randInputs[:3]...)
	h4.SumField() // does not change the digest
	h4.PadBlock()
	h4.WriteField(randInputs[3:]...)
	s := h4.SumField()
	assert.Equal(dgst1, s.Marshal(), "hashes do not match")
}
